=== Method: calc (AbstractMethod) ===


// Estimate the time until when vehicle stop should be detected
// as closer the vehicle comes to standstill as lower get the time limit

if (AxVehComfort >= 0)
{
	tTimeToStandstill = C_CSM_RollPrevtWaitMax;
}
else
{
	tTimeToStandstill = (-VxVehComfort / AxVehComfort) + C_CSM_StandstillDetectionDelay;
	tTimeToStandstill = tTimeToStandstill.min(C_CSM_RollPrevtWaitMax);
}

// Determine whether vehicle was already stopped by brake hold
if(		CsmHoldBrkHoldActive == true
	&& 	VehStop == true	)
{
	BrakeHoldInVehStop = true;
}else if(CsmHoldBrkHoldActive == false )
{
	BrakeHoldInVehStop = false;
}else
{
	BrakeHoldInVehStop = BrakeHoldInVehStop;
}

// Determine the maximum time limit at which a roll prevention shall be enabled
// if vehicle stopped in principle roll prevention shall be immediately available
if(VehStop == true)
{
	TRollPrevDelay = 0;
	
// if roll prevention is already active consider delay timer to give roll prev the chance to stop the vehicle
}else if(CsmHoldRollPrevActive == true)
{
	TRollPrevDelay = C_CSM_RollPrevtWaitForNextRollPrev;
	
// If vehicle was already stopped in the same brake hold the timer should start running to enable roll prev 
}else if(	CsmHoldBrkHoldActive == true
		&&	BrakeHoldInVehStop == true 
		&&  CsmEnaRollPrev == true)
{
	TRollPrevDelay = ((TRollPrevDelay - CycleTime).min(C_CSM_RollPrevtWaitMax)).max(0);
	
// if vehicle was not stopped in the same brake hold the timer should run in case there is no active brake increase (or also rollout) already taking care
}else if(	CsmHoldBrkHoldActive == true
		&&	CsmHoldBrkIncActive == false
		&&	CsmHoldRolloutActive == false
		&&	CsmEnaRollPrev == true)
{
	TRollPrevDelay = ((TRollPrevDelay - CycleTime).min(C_CSM_RollPrevtWaitMax)).max(0);

// in all other cases reset counter maximum limits to avoid unexpected roll prevention
}else
{
	TRollPrevDelay = C_CSM_RollPrevtWaitMaxInBrkHold.min(C_CSM_RollPrevtWaitMax);
	TRollPrevDelay = TRollPrevDelay.min(tTimeToStandstill);
}



// Determine whether a roll prevention is required or not
if(CsmHoldBrkHoldActive == true)
{
	if(CsmHoldRollPrevActive == false)
	{
		CsmHoldRollPrevATarBrk = CsmHoldATarBrk;
	}else{} //Maintain the old value
	
	// Deact Condition which also works if HW limit reached. In that case both values will be set to Thermal Limit.
	if(		CsmHoldRollPrevATarBrk <= CsmHoldRollPrevATarBrkFinal 
		||	CsmEnaRollPrev == false)
	{
		CsmHoldRollPrevActive = false;
	}else{} //Maintain the old value
	
	// Update target value only as long roll prevention isn't active
	if(CsmHoldRollPrevActive == false)
	{
		CsmHoldRollPrevATarBrkFinal = ((CsmHoldATarBrk - C_CSM_RollPrevAOffset).min(CsmHoldABrkThrMax)).max(CsmHoldATarThermLimit);
		CsmjRollPrev    = ((-C_CSM_RollPrevjMin).min((CsmHoldRollPrevATarBrkFinal-CsmHoldATarBrk).min(0)/(C_CSM_RollPrevtReachTarget.max(CycleTime))));
	}else{} // Maintain old values

	// If vehicle isn't stopped and timer has reached its limit and roll prevention is enabled by the feature
	if (	VehStop     == false
		&&	TRollPrevDelay <= 0
		&&	CsmEnaRollPrev == true
		&&	(	(	CsmHoldBrkIncActive == false	// csm is already in an increase state
				&&	CsmHoldRolloutActive == false)	// csm is already in an increase state
			||	CsmHoldRollPrevActive == true							// allow roll prev anyway if already active
			||	AxVehComfort > C_CSM_RollPrevAVehAcceptedWhileBrkInc)	// or if vehicle decel not sufficient
		)
	{
		if(CsmHoldRollPrevActive == false)
		{
			CsmHoldRollPrevCount = CsmHoldRollPrevCount + 1;
		}
		CsmHoldRollPrevActive = true;
	}else{} //Maintain the old value
	
	// Determine actual target value
	if(CsmHoldRollPrevActive == true)
	{
		CsmHoldRollPrevATarBrk = (CsmHoldRollPrevATarBrk + CsmjRollPrev * CycleTime).max(CsmHoldRollPrevATarBrkFinal).max(CsmHoldATarThermLimit);
	}else
	{
		CsmHoldRollPrevATarBrk = 0;
	}
}else
{
	CsmHoldRollPrevActive = false;
	CsmHoldRollPrevATarBrk = 0;
	CsmHoldRollPrevATarBrkFinal = 0;
	CsmHoldRollPrevCount = 0;
	CsmjRollPrev = 0;
}


=== Method: CsmHoldRollPrevActive (AbstractMethod) ===
return CsmHoldRollPrevActive;


=== Method: CsmHoldRollPrevATarBrk (AbstractMethod) ===
return CsmHoldRollPrevATarBrk;


=== Method: CsmHoldRollPrevCount (AbstractMethod) ===
return CsmHoldRollPrevCount;
